package com.bank.subquery.engine;

import com.bank.subquery.model.Txn;
import java.math.*;
import java.util.*;
import java.util.logging.Logger;

public class SubqueryEngine {
    private static final Logger log = Logger.getLogger(SubqueryEngine.class.getName());
    private final List<Txn> txns;
    private long innerExecutions = 0;   // counts how many times the "inner query" runs

    public SubqueryEngine(List<Txn> txns) { this.txns = txns; }

    // CORRELATED: recompute THIS account's average for EACH outer row.
    public List<Txn> correlated() {
        innerExecutions = 0;
        List<Txn> result = new ArrayList<>();
        for (Txn t : txns) {                                  // outer loop
            BigDecimal acctAvg = avgForAccount(t.getAccountId());  // inner runs per outer row
            innerExecutions++;
            if (t.getAmount().compareTo(acctAvg) > 0) result.add(t);
        }
        log.info(() -> "CORRELATED: inner executions = " + innerExecutions + " (one per outer row)");
        return result;
    }

    // NON-CORRELATED: compute the single global average ONCE.
    public List<Txn> nonCorrelated() {
        BigDecimal global = txns.stream().map(Txn::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .divide(BigDecimal.valueOf(txns.size()), 2, RoundingMode.HALF_UP);
        log.info(() -> "NON-CORRELATED: inner executions = 1 (global avg=" + global + ")");
        List<Txn> result = new ArrayList<>();
        for (Txn t : txns) if (t.getAmount().compareTo(global) > 0) result.add(t);
        return result;
    }

    // DECORRELATED (window-style): per-account averages computed ONCE via grouping.
    public List<Txn> decorrelatedWindow() {
        Map<String, List<BigDecimal>> byAcct = new HashMap<>();
        for (Txn t : txns) byAcct.computeIfAbsent(t.getAccountId(), k -> new ArrayList<>()).add(t.getAmount());
        Map<String, BigDecimal> acctAvg = new HashMap<>();
        for (var e : byAcct.entrySet()) {
            BigDecimal sum = e.getValue().stream().reduce(BigDecimal.ZERO, BigDecimal::add);
            acctAvg.put(e.getKey(), sum.divide(BigDecimal.valueOf(e.getValue().size()), 2, RoundingMode.HALF_UP));
        }
        log.info(() -> "DECORRELATED: inner passes = " + acctAvg.size() + " (one per ACCOUNT, not per row)");
        List<Txn> result = new ArrayList<>();
        for (Txn t : txns) if (t.getAmount().compareTo(acctAvg.get(t.getAccountId())) > 0) result.add(t);
        return result;
    }

    private BigDecimal avgForAccount(String accountId) {
        List<BigDecimal> amts = txns.stream().filter(x -> x.getAccountId().equals(accountId))
                .map(Txn::getAmount).toList();
        BigDecimal sum = amts.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
        return sum.divide(BigDecimal.valueOf(amts.size()), 2, RoundingMode.HALF_UP);
    }
}
