package com.bank.subquery;

import com.bank.subquery.engine.SubqueryEngine;
import com.bank.subquery.model.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SubqueryDemo {
    private static final Logger log = Logger.getLogger(SubqueryDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        List<Txn> txns = List.of(
            new Txn(1, "SAV2001", new BigDecimal("10000")),
            new Txn(2, "SAV2001", new BigDecimal("90000")),
            new Txn(3, "CUR3001", new BigDecimal("20000")),
            new Txn(4, "CUR3001", new BigDecimal("60000")),
            new Txn(5, "CUR3001", new BigDecimal("5000")));
        SubqueryEngine eng = new SubqueryEngine(txns);

        log.info("=== Correlated: above OWN account's average ===");
        log.info("result ids=" + ids(eng.correlated()));

        log.info("=== Non-correlated: above GLOBAL average ===");
        log.info("result ids=" + ids(eng.nonCorrelated()));

        log.info("=== Decorrelated window: above own account's average, computed once ===");
        log.info("result ids=" + ids(eng.decorrelatedWindow()));
    }

        private static List<Long> ids(List<Txn> ts) { List<Long> r = new ArrayList<>(); for (Txn t : ts) r.add(t.getId());
        return r; }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

